#include <stdio.h>
#include <string.h>

#define MAX_SIZE 6

char nums[MAX_SIZE];
char filter[MAX_SIZE];

char *map[] = {"abc", "def", "ghi", "jkl", "mno", "pqr", "st", "uv", "wx", "yz"};

void dfs(int level, char path[], int path_size) {
    // 组合层数到达要求时，当前组合字符串完成
    if (nums[level] == '\0') {
        int i = 0;
        while (filter[i] != '\0') {
            if (strchr(path, filter[i]) == NULL) {
                printf("%s,", path);
                return;
            }
            i++;
        }
        return;
    }

    // 当前层级的数字
    int num = nums[level] - '0';
    // 该数字关联的多个字母
    char *letters = map[num];

    // 遍历当前层级可选的字母
    int i = 0;
    while (letters[i] != '\0') {
        // 选择字母加入当前组合
        path[path_size++] = letters[i];
        // 继续组合下一个层级的字母选择
        dfs(level + 1, path, path_size);
        path_size--;
        i++;
    }
}

